app.all(["/api/notifications/:id/read", "/api/notifications/:id/mark-read"], requireAuth, async (req2, res) => {
  const notifId = Number(req2.params.id);
  if (!Number.isFinite(notifId) || notifId <= 0) {
    return res.status(400).json({ error: "Invalid notification ID" });
  }
  try {
    const condition = req2.user.role === "admin" ? eq(notifications.id, notifId) : and(eq(notifications.id, notifId), eq(notifications.userId, req2.user.id));
    const updated = await db.update(notifications).set({ isRead: true }).where(condition).returning({ id: notifications.id });
    if (!updated || updated.length === 0) {
      return res.status(404).json({ error: "Notification not found or access denied" });
    }
    res.json({ success: true });
  } catch (err2) {
    if (!isLocalFallbackAllowed) {
      return res.status(503).json({ error: "Database unavailable" });
    }
    res.json({ success: true });
  }
});
